var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
var gm = GameState.state.units["U_CUSTODIAN_GUARD_A"].models
gm[gm.size() - 1]["alive"] = false
gm[gm.size() - 1]["current_wounds"] = 0
return H.setup(1, "Honoured Companions", {})

var main = tree.current_scene
