PhaseManager.transition_to_phase(10)
return int(GameState.get_current_phase())

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return H.window_id()

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return H.decider()

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return main.get_tree().root.get_node("StratagemDialog/Content/Header").text.to_lower().contains("selected to fight")

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return H.flag("U_CUSTODIAN_GUARD_A", "cus11e_avenge_the_fallen")

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return H.codex().bonus_attacks_per_model(H.unit("U_CUSTODIAN_GUARD_A"), H.unit("U_BOYZ_B"), {}, false, true)

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return H.log_count("Used AVENGE THE FALLEN")

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return "U_CUSTODIAN_GUARD_A" in H.phase().units_that_fought
